package com.playercompass;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(PlayerCompassConfig.GROUP)
public interface PlayerCompassConfig extends Config
{
	String GROUP = "player-compass";

	@ConfigItem(
		keyName = "enabled",
		name = "Enable compass",
		description = "Display the compass around your tile",
		position = 0
	)
	default boolean enabled()
	{
		return true;
	}

	@Range(min = -100, max = 100)
	@ConfigItem(
		keyName = "verticalOffset",
		name = "Vertical offset",
		description = "Move the compass vertically from the true tile center",
		position = 1
	)
	default int verticalOffset()
	{
		return 0;
	}

	@Range(min = 6, max = 100)
	@ConfigItem(
		keyName = "compassSize",
		name = "Compass size",
		description = "Distance in pixels from the compass center to each letter",
		position = 2
	)
	default int compassSize()
	{
		return 40;
	}

	@Range(min = 8, max = 40)
	@ConfigItem(
		keyName = "letterSize",
		name = "Letter size",
		description = "Font size of the compass letters",
		position = 3
	)
	default int letterSize()
	{
		return 14;
	}

	@Alpha
	@ConfigItem(
		keyName = "textColor",
		name = "Text color",
		description = "Color of the compass letters",
		position = 4
	)
	default Color textColor()
	{
		return Color.WHITE;
	}

	@Alpha
	@ConfigItem(
		keyName = "outlineColor",
		name = "Outline color",
		description = "Color around the compass letters",
		position = 5
	)
	default Color outlineColor()
	{
		return Color.BLACK;
	}

	@ConfigItem(
		keyName = "shadow",
		name = "Draw shadow",
		description = "Draw a drop shadow behind the compass letters",
		position = 6
	)
	default boolean shadow()
	{
		return true;
	}
}

package com.playercompass;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws true world directions around the local player's tile.
 */
@Singleton
public final class PlayerCompassOverlay extends Overlay
{
	private static final String NORTH = "N";
	private static final String EAST = "E";
	private static final String SOUTH = "S";
	private static final String WEST = "W";
	private static final Color SHADOW_COLOR = new Color(0, 0, 0, 160);

	private final Client client;
	private final PlayerCompassConfig config;

	private Font font;
	private Font sourceFont;
	private int fontSize = -1;

	@Inject
	private PlayerCompassOverlay(Client client, PlayerCompassConfig config)
	{
		this.client = client;
		this.config = config;
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(PRIORITY_MED);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.enabled())
		{
			return null;
		}

		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return null;
		}

		WorldPoint worldPoint = player.getWorldLocation();
		LocalPoint centerLocal = LocalPoint.fromWorld(client, worldPoint);
		if (centerLocal == null)
		{
			return null;
		}

		int plane = worldPoint.getPlane();
		Point center = Perspective.localToCanvas(client, centerLocal, plane);
		Point north = Perspective.localToCanvas(client, centerLocal.dy(Perspective.LOCAL_TILE_SIZE), plane);
		Point east = Perspective.localToCanvas(client, centerLocal.dx(Perspective.LOCAL_TILE_SIZE), plane);
		Point south = Perspective.localToCanvas(client, centerLocal.dy(-Perspective.LOCAL_TILE_SIZE), plane);
		Point west = Perspective.localToCanvas(client, centerLocal.dx(-Perspective.LOCAL_TILE_SIZE), plane);
		if (center == null || north == null || east == null || south == null || west == null)
		{
			return null;
		}

		int centerX = center.getX();
		int centerY = center.getY() + config.verticalOffset();

		Font originalFont = graphics.getFont();
		Color originalColor = graphics.getColor();
		try
		{
			graphics.setFont(fontFor(originalFont, config.letterSize()));
			FontMetrics metrics = graphics.getFontMetrics();
			int radius = config.compassSize();
			Color textColor = config.textColor();
			Color outlineColor = config.outlineColor();
			boolean shadow = config.shadow();

			drawDirection(graphics, metrics, NORTH, center, north, centerX, centerY, radius, textColor, outlineColor, shadow);
			drawDirection(graphics, metrics, EAST, center, east, centerX, centerY, radius, textColor, outlineColor, shadow);
			drawDirection(graphics, metrics, SOUTH, center, south, centerX, centerY, radius, textColor, outlineColor, shadow);
			drawDirection(graphics, metrics, WEST, center, west, centerX, centerY, radius, textColor, outlineColor, shadow);
		}
		finally
		{
			graphics.setFont(originalFont);
			graphics.setColor(originalColor);
		}

		return null;
	}

	private Font fontFor(Font baseFont, int size)
	{
		if (font == null || sourceFont != baseFont || fontSize != size)
		{
			sourceFont = baseFont;
			fontSize = size;
			font = baseFont.deriveFont(Font.BOLD, (float) size);
		}
		return font;
	}

	private static void drawDirection(
		Graphics2D graphics,
		FontMetrics metrics,
		String letter,
		Point center,
		Point direction,
		int centerX,
		int centerY,
		int radius,
		Color textColor,
		Color outlineColor,
		boolean shadow)
	{
		int dx = direction.getX() - center.getX();
		int dy = direction.getY() - center.getY();
		double length = Math.hypot(dx, dy);
		if (length == 0)
		{
			return;
		}

		int x = centerX + (int) Math.round(dx * radius / length);
		int y = centerY + (int) Math.round(dy * radius / length);
		drawLetter(graphics, metrics, letter, x, y, textColor, outlineColor, shadow);
	}

	private static void drawLetter(
		Graphics2D graphics,
		FontMetrics metrics,
		String letter,
		int centerX,
		int centerY,
		Color textColor,
		Color outlineColor,
		boolean shadow)
	{
		int x = centerX - metrics.stringWidth(letter) / 2;
		int y = centerY + (metrics.getAscent() - metrics.getDescent()) / 2;

		if (shadow)
		{
			graphics.setColor(SHADOW_COLOR);
			graphics.drawString(letter, x + 2, y + 2);
		}

		graphics.setColor(outlineColor);
		graphics.drawString(letter, x - 1, y - 1);
		graphics.drawString(letter, x, y - 1);
		graphics.drawString(letter, x + 1, y - 1);
		graphics.drawString(letter, x - 1, y);
		graphics.drawString(letter, x + 1, y);
		graphics.drawString(letter, x - 1, y + 1);
		graphics.drawString(letter, x, y + 1);
		graphics.drawString(letter, x + 1, y + 1);

		graphics.setColor(textColor);
		graphics.drawString(letter, x, y);
	}
}

package com.playercompass;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Player Compass",
	description = "Displays a static compass around the local player's true tile",
	tags = {"player", "compass", "direction", "overlay"}
)
public class PlayerCompassPlugin extends Plugin
{
	@Inject
	private OverlayManager overlayManager;

	@Inject
	private PlayerCompassOverlay overlay;

	@Provides
	PlayerCompassConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(PlayerCompassConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
	}
}

/**
 * Provides the Player Compass RuneLite plugin.
 */
package com.playercompass;

package com.playercompass;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class PluginLauncher
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(PlayerCompassPlugin.class);
		RuneLite.main(args);
	}
}
